        let holds = enclave_holds_key(app_label)?;
        if holds {
            remember_enclave_probe(did);
        }
        Ok(holds)
    },
)?;

if let SeFastPath::UseCached(compressed) = verdict {
    return Ok(crate::device_key::make_device_public_key(&compressed));
