    let result = classify_se_fast_path(
        MetadataItem::Present(vec![0x02; 33]),
        MetadataItem::Present(b"app-label".to_vec()),
        |_| Ok(false),
    );

    assert!(
        matches!(result, Err(IdentityStoreError::DeviceKeyUnusable)),
        "expected DeviceKeyUnusable, got {result:?}"
    );
}

